PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>

SELECT  ?var1 ?var2
WHERE
  { ?var1  wdt:P31  wde:Q5
    {   { ?var1  wdt:P27  wde:Q20 }
      UNION
        { ?var1  wdt:P27  wde:Q34 }
      UNION
        { ?var1  wdt:P27  wde:Q35 }
      UNION
        { ?var1  wdt:P27  wde:Q33 }
      UNION
        { ?var1  wdt:P27  wde:Q191 }
    }
    MINUS
      { ?var1  wdt:P734  ?var3 }
    BIND(xsd:integer(substr(str(?var1), 33)) AS ?var2)
  }
ORDER BY DESC(?var2)

