PREFIX  url:  <http://schema.org/>

SELECT  ?var1Label ?var2 ?var3 ?var4 ?var5 ?var6
WHERE
  { OPTIONAL
      { wde:Q72  rdfs:label  ?var1Label
        FILTER ( lang(?var1Label) = ?var7 )
        VALUES ( ?var7 ?var8 ) {
          ( "undefined" 1 )
          ( "en" 2 )
          ( "de" 3 )
          ( "fr" 4 )
          ( "it" 5 )
        }
      }
    OPTIONAL
      { wde:Q72  wdt:P18  ?var3 }
    OPTIONAL
      { wde:Q72  <urn:dboabstract>  ?var2
        FILTER ( lang(?var2) = "undefined" )
      }
    OPTIONAL
      { wde:Q72  wdt:P625  ?var4 }
    OPTIONAL
      { ?var6  rdf:type        url:Article ;
               url:about       wde:Q72 ;
               url:inLanguage  "undefined" ;
               url:isPartOf    <https://undefined.wikipedia.org/>
      }
  }
ORDER BY ASC(?var8)

PREFIX  rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX  wdt:  <http://www.wikidata.org/prop/direct/>
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  wde:  <http://www.wikidata.org/entity/>
PREFIX  rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX  url:  <http://schema.org/>

SELECT  ?var1Label ?var2 ?var3 ?var4 ?var5 ?var6 ?var7 ?var8 ?var9 ?var10 ?var11
WHERE
  { OPTIONAL
      { wde:Q92764  rdfs:label  ?var1Label
        FILTER ( lang(?var1Label) = ?var12 )
        VALUES ( ?var12 ?var13 ) {
          ( "en" 1 )
          ( "en" 2 )
          ( "de" 3 )
          ( "fr" 4 )
          ( "it" 5 )
        }
      }
    OPTIONAL
      { wde:Q92764  wdt:P18  ?var2 }
    OPTIONAL
      { wde:Q92764  wdt:P625  ?var3 }
    OPTIONAL
      { wde:Q92764  wdt:P1651  ?var5 }
    OPTIONAL
      { wde:Q92764  wdt:P2037  ?var6 }
    OPTIONAL
      { wde:Q92764  wdt:P2002  ?var7 }
    OPTIONAL
      { wde:Q92764  wdt:P2013  ?var8 }
    OPTIONAL
      { wde:Q92764  wdt:P2003  ?var9 }
    OPTIONAL
      { wde:Q92764  wdt:P856  ?var10 }
    OPTIONAL
      { wde:Q92764  wdt:P496  ?var11 }
    OPTIONAL
      { ?var4  rdf:type        url:Article ;
               url:about       wde:Q92764 ;
               url:inLanguage  "en" ;
               url:isPartOf    <https://en.wikipedia.org/>
      }
  }
ORDER BY ASC(?var13)
